fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> Vec<i32> {
    let n = s1.len();
    assert_eq!(s2.len(), n, "All input arrays must have the same length");
    assert_eq!(s3.len(), n, "All input arrays must have the same length");

    let mut res = Vec::with_capacity(3 * n);
    for i in 0..n {
        res.push(s1[i]);
        res.push(s2[i]);
        res.push(s3[i]);
    }
    res
}

